export type FindingStatus = "draft" | "approved" | "rejected" | "unverified";

export type Confidence = "low" | "medium" | "high";

export type TaskStatus = "pending" | "running" | "completed" | "failed" | "skipped";

export type RunStatus =
  | "queued"
  | "planning"
  | "researching"
  | "reviewing"
  | "revising"
  | "awaiting_approval"
  | "writing"
  | "completed"
  | "failed"
  | "cancelled";

export const TERMINAL_RUN_STATUSES: readonly RunStatus[] = ["completed", "failed", "cancelled"];

export type SourceKind =
  | "sec_filing"
  | "xbrl_facts"
  | "market_data"
  | "news"
  | "macro"
  | "company_profile"
  | "peer_data"
  | "document"
  | "calculation";

export type RiskCategory =
  | "financial"
  | "liquidity"
  | "debt"
  | "competitive"
  | "regulatory"
  | "operational"
  | "concentration"
  | "geopolitical"
  | "technology"
  | "valuation";

export type Verdict = "approved" | "needs_revision" | "rejected";

export type CriticIssueType =
  | "unsupported_claim"
  | "inconsistent_figure"
  | "stale_information"
  | "contradiction"
  | "calculation_error"
  | "missing_citation"
  | "hallucination"
  | "weak_assumption"
  | "duplication";

export type Severity = "low" | "medium" | "high";

export type FeedbackAction =
  | "approve"
  | "deepen_valuation"
  | "add_competitor"
  | "add_risk_analysis"
  | "rerun_agent"
  | "comment";

// ---------------------------------------------------------------------------
// Wire-format date/time aliases
// ---------------------------------------------------------------------------

/** ISO-8601 datetime string, e.g. "2026-09-24T14:03:00Z". */
export type IsoDateTime = string;

/** ISO-8601 calendar date string, e.g. "2026-09-24". */
export type IsoDate = string;

